function improplot(nmat,wlen,tmin,tmax);warning offwstep=1;on=onsetsecs(nmat); dur=dursecs(nmat);if nargin<3	tmin=0; tmax=on(end)+dur(end);endif nargin<2    wlen=6;    disp('Window length set to 6 secs.');endnm1=getmidich(nmat,1);nm2=getmidich(nmat,2);t=tmin:wstep:tmax;stdp1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','pitch','std');stdp2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','pitch','std');meanp1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','pitch','mean');meanp2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','pitch','mean');meanv1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','velocity','mean');meanv2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','velocity','mean');ton1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','maxkkcc');ton2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','maxkkcc');dens1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','nnotes')/wlen;dens2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','nnotes')/wlen;dur1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','dursecs','mean');dur2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','dursecs','mean');ac1=movewindow(nm1,tmin,tmax,wlen,wstep,'sec','pulseclarity');ac2=movewindow(nm2,tmin,tmax,wlen,wstep,'sec','pulseclarity');N=9;clf;subplot(N,1,1),pianoroll(nm1);axis([tmin tmax get(gca,'YLim')]);subplot(N,1,2),pianoroll(nm2);axis([tmin tmax get(gca,'YLim')]);maxdens=max([dens1; dens2]);subplot(N,1,3),plot(t,dens1,'b-'); axis([tmin tmax 0 maxdens]),hold onplot(t,dens2,'r-');hold offylabel('density');maxdur=max([dur1; dur2]);subplot(N,1,4),plot(t,dur1,'b-'); axis([tmin tmax 0 maxdur]),hold onplot(t,dur2,'r-');hold offylabel('mean dur');subplot(N,1,5),plot(t,meanp1,'b-'); axis([tmin tmax 0 127]),hold onplot(t,meanp2,'r-');hold off;ylabel('mean pitch');pran=max([stdp1;stdp2]);subplot(N,1,6),plot(t,stdp1,'b-'); axis([tmin tmax 0 pran]),hold onplot(t,stdp2,'r-'); hold offylabel('pitch std');subplot(N,1,7),plot(t,meanv1,'b-'); axis([tmin tmax 0 127]),hold onplot(t,meanv2,'r-'); hold offylabel('mean vel');acran=max([ac1;ac2]);subplot(N,1,8),plot(t,ac1,'b-'); axis([tmin tmax 0 acran]),hold onplot(t,ac2,'r-'); hold offylabel('pulseclar');subplot(N,1,9),plot(t,ton1,'b-'); axis([tmin tmax 0 1]),hold onplot(t,ton2,'r-');hold offylabel('tonality');